contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        require(true);
        uint beforeSelf = address(this).balance;
        uint beforeC = address(c).balance;
        bool reverted;
        try c.go{value: 0}() { reverted = false; } catch { reverted = true; }
        uint afterSelf = address(this).balance;
        uint afterC = address(c).balance;
        uint ownerAfter = c.owner();
        // A zero-value go() must never revert, must keep C empty, must leave
        // the caller's Ether exactly unchanged, and must not change the owner.
        assert(!reverted && afterC == 0 && afterSelf == beforeSelf - (beforeC) && ownerAfter == c.owner());
    }
    receive() external payable {}
    fallback() external payable {}
}

